CREATE TABLE employment_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, staff_identity_id BIGINT UNSIGNED NOT NULL, effective_from DATE NULL, effective_until DATE NULL, previous_organisation_id BIGINT UNSIGNED NULL, organisation_id BIGINT UNSIGNED NULL, position_id BIGINT UNSIGNED NULL, grade_id BIGINT UNSIGNED NULL, change_reason VARCHAR(500) NOT NULL, changed_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(staff_identity_id) REFERENCES staff_identities(id), FOREIGN KEY(previous_organisation_id) REFERENCES organisations(id), FOREIGN KEY(organisation_id) REFERENCES organisations(id), FOREIGN KEY(position_id) REFERENCES master_data(id), FOREIGN KEY(grade_id) REFERENCES master_data(id), FOREIGN KEY(changed_by) REFERENCES users(id), INDEX(staff_identity_id,effective_from), CHECK(effective_until IS NULL OR effective_from IS NULL OR effective_until>=effective_from)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
